WITH with_prev AS (SELECT *, LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time, id) AS prev_event_time FROM web_events), with_gaps AS (SELECT *, CASE WHEN prev_event_time IS NULL OR event_time > prev_event_time + INTERVAL 90 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM with_prev), sessions_web_events AS (SELECT id, event_type, page, event_time, duration_sec, SUM(session_start_flag) OVER (PARTITION BY event_type ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT id, event_type, event_time, duration_sec, burst_id FROM sessions_web_events ORDER BY event_time DESC NULLS LAST
